pRequestMessage>Q(HttpMethod m,string u){var q=new HttpRequestMessage(m,u);var token=await(c.HttpContext??throw new InvalidOperationException()).GetTokenAsync("access_token");q.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);return q;}}
